package com.aryan.reader

import android.content.Context
import android.os.ParcelFileDescriptor
import androidx.test.core.app.ApplicationProvider
import androidx.test.ext.junit.runners.AndroidJUnit4
import com.aryan.reader.shared.FileType
import com.google.common.truth.Truth.assertThat
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File
import java.util.Base64

/**
 * Exercises the libarchive named-entry read on a real device. The JNI reader is
 * Android-only, so this cannot be covered by a JVM unit test.
 */
@RunWith(AndroidJUnit4::class)
class ComicInfoArchiveReaderLibarchiveTest {
    private val context = ApplicationProvider.getApplicationContext<Context>()

    @Test
    fun cbr_reads_comicinfo_through_the_archive_descriptor() {
        val metadata = readFixture(FileType.CBR, CBR_WITH_COMIC_INFO_FIXTURE)

        assertThat(metadata?.title).isEqualTo("Court of Owls")
        assertThat(metadata?.author).isEqualTo("Scott Snyder")
        assertThat(metadata?.seriesName).isEqualTo("Batman")
        assertThat(metadata?.seriesIndex).isEqualTo(5.0)
        assertThat(metadata?.description).isEqualTo("Owls everywhere.")
    }

    @Test
    fun cb7_reads_comicinfo_through_the_archive_descriptor() {
        val metadata = readFixture(FileType.CB7, CB7_WITH_COMIC_INFO_FIXTURE)

        assertThat(metadata?.title).isEqualTo("Court of Owls")
        assertThat(metadata?.author).isEqualTo("Scott Snyder")
        assertThat(metadata?.seriesName).isEqualTo("Batman")
        assertThat(metadata?.seriesIndex).isEqualTo(5.0)
        assertThat(metadata?.description).isEqualTo("Owls everywhere.")
    }

    @Test
    fun cbt_reads_comicinfo_through_the_archive_descriptor() {
        val metadata = readFixture(FileType.CBT, CBT_WITH_COMIC_INFO_FIXTURE)

        assertThat(metadata?.title).isEqualTo("Court of Owls")
        assertThat(metadata?.author).isEqualTo("Scott Snyder")
        assertThat(metadata?.seriesName).isEqualTo("Batman")
        assertThat(metadata?.seriesIndex).isEqualTo(5.0)
        assertThat(metadata?.description).isEqualTo("Owls everywhere.")
    }

    private fun readFixture(type: FileType, base64: String): com.aryan.reader.shared.SharedComicInfoMetadata? {
        val file = File(context.cacheDir, "comicinfo-${type.name.lowercase()}.${type.name.lowercase()}")
        file.writeBytes(Base64.getDecoder().decode(base64))
        return try {
            ComicInfoArchiveReader.read(
                type = type,
                openStream = { file.inputStream() },
                openFileDescriptor = {
                    ParcelFileDescriptor.open(file, ParcelFileDescriptor.MODE_READ_ONLY)
                },
                cacheDir = context.cacheDir
            )
        } finally {
            file.delete()
        }
    }

    private companion object {
        private const val CBR_WITH_COMIC_INFO_FIXTURE =
            ""

        private const val CBT_WITH_COMIC_INFO_FIXTURE =
            ""

        private const val CB7_WITH_COMIC_INFO_FIXTURE =
            ""
    }
}
